// Five original scores composed for Quest Clash. No recordings, samples, melodies or assets from references.
const BIOME_SCORES={
meadow:{name:'Wildwood Signal',bpm:116,roots:[48,53,55,48,57,53,55,48],motif:[0,4,7,12,7,4,2,-99,0,7,9,7,4,2,0,-99],voice:'triangle',colour:'#a8d98d'},
dinosaur:{name:'Ancient Canopy',bpm:124,roots:[45,45,48,43,45,48,50,43],motif:[0,-99,3,7,10,7,3,-99,0,3,5,7,3,0,-99,7],voice:'sine',colour:'#d1ad70'},
lunar:{name:'Orbital Current',bpm:128,roots:[47,50,45,52,47,50,54,45],motif:[0,7,12,14,7,12,3,-99,0,3,10,14,12,7,3,7],voice:'triangle',colour:'#7ed8ed'},
water:{name:'Below the Blue',bpm:98,roots:[50,55,57,53,50,57,55,53],motif:[0,-99,7,9,12,-99,9,7,4,-99,2,7,9,7,4,-99],voice:'sine',colour:'#8ddcdd'},
zombie:{name:'Afterlight Patrol',bpm:110,roots:[45,48,43,46,45,43,41,43],motif:[0,-99,7,3,-99,5,3,-99,0,3,-99,10,7,3,2,-99],voice:'triangle',colour:'#c4d38d'}
};
function currentBiomeScore(){const kind=game?.map?.terrain||GameAudio.previewBiome||(typeof selectedMap==='function'?selectedMap().terrain:'meadow')||'meadow';return{kind,...(BIOME_SCORES[kind]||BIOME_SCORES.meadow)}}
GameAudio.schedule=function(){if(!this.ctx||document.hidden||!profile.music||this.ctx.state!=='running')return;const score=currentBiomeScore(),now=this.ctx.currentTime;if(this.biomeKey!==score.kind){this.biomeKey=score.kind;this.step=0;this.nextBeat=Math.max(this.nextBeat,now+.04)}if(this.nextBeat<now-.25)this.nextBeat=now+.03;let count=0;while(this.nextBeat<now+.2&&count++<12){this.musicStep(this.step++,this.nextBeat);const boss=game&&!game.paused&&game.boss?.hp>0,bpm=score.bpm+(boss?12:game&&!game.paused?4:-8);this.nextBeat+=60/bpm/2/MUSIC_SPEED}};
GameAudio.musicStep=function(step,time){const score=currentBiomeScore(),battle=!!game&&!game.paused,reading=modal.open,boss=battle&&game.boss?.hp>0,bar=Math.floor(step/8)%8,beat=step%8,root=score.roots[bar],midi=n=>440*2**((n-69)/12),bus=this.musicBus,duck=time<this.duckUntil?.1:reading?.27:1,level=duck*(battle?1:.7),interval=score.motif[step%16],track=score.name+(boss?' · Guardian':'');if(this.trackName!==track){this.trackName=track;const el=document.querySelector('#music-track');if(el)el.textContent=track}if(interval>-90&&(battle||!reading||beat%2===0)){const note=root+24+interval+(bar>=4&&beat===6?12:0);this.voice(midi(note),time,score.kind==='water'?.42:.17,.115*level,score.voice,bus);if(score.kind==='lunar')this.voice(midi(note+7),time+.07,.1,.025*level,'sine',bus);if(score.kind==='dinosaur')this.voice(midi(note-12),time,.065,.045*level,'triangle',bus)}if([0,3,4,6].includes(beat)){const n=root-12+(beat===3||beat===6?7:0);this.voice(midi(n),time,.22,.22*level,score.kind==='zombie'?'sawtooth':'triangle',bus)}if(beat===0||beat===4){const minor=['dinosaur','lunar','zombie'].includes(score.kind);for(const n of [0,minor?3:4,7])this.voice(midi(root+n),time,score.kind==='water'?.65:.33,.035*level,'sine',bus)}if(!reading){if(beat===0||beat===4)this.voice(score.kind==='dinosaur'?125:140,time,.16,.26*level,'sine',bus,45);if(beat===2||beat===6){if(score.kind==='dinosaur')this.voice(185,time,.13,.14*level,'sine',bus,78);else this.noise(time,.07,.065*level,score.kind==='water'?3500:1300,bus)}if(score.kind!=='water'||beat%2===1)this.noise(time,.025,(score.kind==='water'?.014:.033)*level,6200,bus);if(bar===7&&beat===7)this.voice(midi(root+19),time+.08,.09,.06*level,'triangle',bus)}};

if(typeof openCoursePreview==='function'){const scoredCoursePreview=openCoursePreview;openCoursePreview=function(mode,id){GameAudio.previewBiome=courseMap(mode,id).terrain;scoredCoursePreview(mode,id)};const scoredModalClose=closeModal;closeModal=function(){GameAudio.previewBiome=null;scoredModalClose()}}
